import {mountLanding} from './landing.js';
import {boundary,inside,search} from './core.js';
import {geometry,validatePolygon} from './geometry.js';
import {parameters,summarize} from './field-profile.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createOnboarding({getFarms,onConfirm,onOpen}){
 const host=document.createElement('div');host.id='onboarding';document.body.append(host);
 let map=null,ring=[],mode='polygon',complete=false,layer=null,markers=[],reviewId=0,climate=null,profile=null,selected=null,name='Mi finca',focus=[-4.926,-80.344];
 const $=s=>host.querySelector(s);
 function clean(){reviewId++;if(map){map.remove();map=null;}host.innerHTML='';document.body.classList.add('onboarding');host.hidden=false;}
 const header=()=>`<div class="flow-header"><div class="flow-logo">◈ NORTEX<small>TAMBO · VALLE DE SAN LORENZO</small></div><span class="badge">TU TIERRA. TUS DECISIONES.</span></div>`;
 function landing(){clean();mountLanding(host,{onBegin:()=>drawMap(),onExplore:id=>open(id)});}
 function baseMap(id,editing=false){const m=L.map(id,{zoomControl:false,minZoom:10,maxZoom:19,maxBounds:[[-5.03,-80.44],[-4.58,-80.02]],maxBoundsViscosity:1,doubleClickZoom:!editing});L.control.zoom({position:'topright'}).addTo(m);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(m);L.polygon(boundary.map(([x,y])=>[y,x]),{color:'#829366',weight:2,dashArray:'6 6',fillOpacity:.045,interactive:false}).addTo(m);return m;}
 function drawMap(){clean();climate=null;profile=null;host.innerHTML=`<div class="flow-mapview"><div id="fieldMap" class="flow-map" aria-label="Mapa de Tambogrande para dibujar el terreno"></div><button class="flow-mapback" id="backHome">← Inicio</button><div class="flow-searchbox"><form id="findFarm"><input id="farmQuery" aria-label="Buscar mi finca o zona" placeholder="Buscar zona, finca guardada o latitud, longitud"><button class="primary">Buscar</button></form><small>TAMBOGRANDE / SAN LORENZO · Búsqueda dentro de la zona piloto</small><div id="flowResults"></div></div><div class="flow-tools"><h3>Traza tu terreno</h3><div class="shape-buttons"><button data-shape="rectangle">▱ Rectángulo</button><button data-shape="triangle">△ Triángulo</button><button data-shape="polygon">⬡ Polígono libre</button></div><p id="drawHelp"></p><div class="flow-smallbuttons"><button id="undoVertex">Deshacer</button><button id="clearShape">Borrar figura</button></div><button id="finishShape" style="width:100%;margin-top:9px">Cerrar polígono</button></div><div class="flow-bottom"><div><strong id="areaValue">Dibuja tu finca</strong><small id="drawStatus" role="status">Marca los vértices dentro del límite provisional.</small></div><button class="primary" id="reviewArea" disabled>Revisar esta zona →</button></div></div>`;
 $('#backHome').onclick=landing;
 if(!window.L){$('#drawStatus').textContent='No se pudo cargar el mapa. Comprueba tu conexión y vuelve a intentar.';return;}
 map=baseMap('fieldMap',true);if(ring.length>=3)map.fitBounds(ring.map(([x,y])=>[y,x]),{padding:[90,90],maxZoom:17});else map.setView(focus,13);
 $('#findFarm').onsubmit=e=>{e.preventDefault();const q=$('#farmQuery').value.trim(),parts=q.split(',').map(Number);let hits=q.includes(',')&&parts.length===2&&parts.every(Number.isFinite)?[{name:'Coordenadas buscadas',lat:parts[0],lon:parts[1]}]:search(q,getFarms());hits=hits.filter(p=>inside(p.lat,p.lon));$('#flowResults').innerHTML=hits.length?hits.map((p,i)=>`<button data-hit="${i}">${esc(p.name)} ↗</button>`).join(''):'<p>No hay resultados dentro de la zona piloto. Puedes explorar el mapa.</p>';$('#flowResults').querySelectorAll('button').forEach(b=>b.onclick=()=>{let p=hits[+b.dataset.hit];focus=[p.lat,p.lon];map.setView(focus,16);$('#flowResults').innerHTML='';$('#farmQuery').value=p.name;});};
 host.querySelectorAll('[data-shape]').forEach(b=>b.onclick=()=>{mode=b.dataset.shape;ring=[];complete=false;paint();});
 $('#undoVertex').onclick=()=>{if(mode==='rectangle'){ring=[];}else ring.pop();complete=false;paint();};$('#clearShape').onclick=()=>{ring=[];complete=false;paint();};$('#finishShape').onclick=()=>{if(ring.length<3)return;complete=true;paint();};$('#reviewArea').onclick=review;
 map.on('click',e=>{if(complete)return;const p=[e.latlng.lng,e.latlng.lat];if(!inside(p[1],p[0])){$('#drawStatus').textContent='Selecciona dentro de la zona piloto.';return;}if(ring.length>=80)return;if(mode==='rectangle'&&ring.length===1){const a=ring[0];ring=[a,[p[0],a[1]],p,[a[0],p[1]]];complete=true;}else{ring.push(p);if(mode==='triangle'&&ring.length===3)complete=true;}paint();});paint();
 }
 function paint(){if(layer)map.removeLayer(layer);markers.forEach(m=>map.removeLayer(m));markers=[];layer=null;
 host.querySelectorAll('[data-shape]').forEach(b=>b.classList.toggle('active',b.dataset.shape===mode));
 $('#drawHelp').textContent=complete?'Arrastra los vértices para ajustar la figura a tu terreno.':mode==='rectangle'?'Haz clic en dos esquinas opuestas.':mode==='triangle'?'Haz clic en los tres vértices del triángulo.':'Marca cada vértice y pulsa «Cerrar polígono».';
 if(ring.length>1){layer=(complete?L.polygon:L.polyline)(ring.map(([x,y])=>[y,x]),{color:'#215b45',weight:3,fillColor:'#afcf79',fillOpacity:.3,interactive:false}).addTo(map);}
 ring.forEach((p,i)=>{const m=L.marker([p[1],p[0]],{draggable:true,icon:L.divIcon({className:'vertex',iconSize:[18,18],iconAnchor:[9,9]}),title:`Vértice ${i+1}`,autoPan:true}).addTo(map);m.on('dragend',()=>{const pos=m.getLatLng();ring[i]=[pos.lng,pos.lat];paint();});markers.push(m);});
 const error=complete?validatePolygon(ring):null;$('#areaValue').textContent=complete&&!error?`${geometry(ring).hectares.toLocaleString('es-PE',{maximumFractionDigits:2})} ha`:ring.length?`${ring.length} vértices marcados`:'Dibuja tu finca';
 $('#drawStatus').textContent=error|| (complete?'Superficie aproximada. Revisa la figura antes de continuar.':'Tu selección debe ser una figura cerrada, no un punto.');$('#drawStatus').classList.toggle('flow-error',!!error);$('#reviewArea').disabled=!complete||!!error;$('#finishShape').hidden=mode!=='polygon'||complete;$('#finishShape').disabled=ring.length<3;$('#undoVertex').disabled=!ring.length;
 }
 function review(){if(validatePolygon(ring))return;clean();const id=reviewId,g=geometry(ring);selected={...g,vertices:ring.map(p=>[...p]),status:'dibujado por usuario; superficie aproximada',boundary:'piloto provisional'};
 host.innerHTML=header()+`<div class="review-wrap"><div class="review-heading"><div><small class="eyebrow">PASO 03 / REVISA TU TERRENO</small><h1>¿Esta es tu finca?</h1><p>Comprueba la figura y la información disponible antes de continuar.</p></div><span class="flow-statuspill">Zona dentro del piloto</span></div><div class="review-grid"><div class="card"><div id="reviewMap" class="review-map"></div><label style="margin-top:16px">Nombre de la finca (opcional)<input id="fieldName" maxlength="100" value="${esc(name)}"></label><div class="row"><span>Superficie dibujada</span><strong>${g.hectares.toFixed(2)} ha</strong></div><div class="row"><span>Perímetro aproximado</span><strong>${g.perimeter_m.toFixed(0)} m</strong></div><div class="row"><span>Forma</span><strong>${ring.length} vértices</strong></div><p>La superficie se calcula a partir de tu dibujo. No reemplaza un levantamiento catastral.</p></div><div class="card"><h2>Datos de esta zona</h2><p>El área proviene del polígono. Para el clima usamos un punto interior de referencia: ${g.reference.lat.toFixed(4)}, ${g.reference.lon.toFixed(4)}.</p><div class="notice">NASA POWER es de escala regional. Esta consulta no es un promedio espacial del terreno ni una medición de cada parte de tu finca.</div><button id="loadZone" class="primary">Consultar datos de la zona</button><p style="font-size:11px">Se enviarán únicamente las coordenadas de referencia a NASA POWER.</p><div id="zoneStatus" class="review-status" role="status">Puedes consultar el histórico de 2025 antes de confirmar.</div><div id="zoneData"></div><p>Cultivo, suelo, humedad radicular y turnos de riego: pendientes de confirmar. No se completan con supuestos.</p></div></div><div class="review-actions"><button id="editZone">← Ajustar figura</button><p>Al confirmar entrarás al espacio de análisis y planificación de NORTEX. El terreno se conserva en este navegador.</p><button class="primary" id="confirmZone">Confirmar finca y continuar →</button></div></div>`;
 map=baseMap('reviewMap');L.polygon(ring.map(([x,y])=>[y,x]),{color:'#215b45',fillColor:'#afcf79',fillOpacity:.35}).addTo(map);map.fitBounds(ring.map(([x,y])=>[y,x]),{padding:[25,25],maxZoom:17});
 $('#editZone').onclick=()=>{name=$('#fieldName').value.trim()||'Mi finca';drawMap();};$('#confirmZone').onclick=()=>{name=$('#fieldName').value.trim()||'Mi finca';selected.name=name;selected.profile=profile;try{localStorage.setItem('nortex-selected-area',JSON.stringify(selected));}catch{}onConfirm(selected,climate);purpose();};
 $('#loadZone').onclick=async()=>{const btn=$('#loadZone');btn.disabled=true;$('#zoneStatus').textContent='Consultando datos históricos…';try{const p=g.reference,key=`nortex-profile-v1-${p.lat.toFixed(3)}-${p.lon.toFixed(3)}`;let data;try{data=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(!data){const query=new URLSearchParams({parameters:parameters.join(','),community:'AG',latitude:p.lat.toFixed(3),longitude:p.lon.toFixed(3),start:'20250101',end:'20251231',format:'JSON','time-standard':'LST'});const res=await fetch(`https://power.larc.nasa.gov/api/temporal/daily/point?${query}`,{signal:AbortSignal.timeout(45000)});if(!res.ok)throw Error(`NASA respondió ${res.status}`);data=await res.json();}const summary=summarize(data,p);if(!summary.fields.some(f=>f.value!==null))throw Error('Sin datos válidos');if(id!==reviewId)return;climate=data;profile=summary;try{localStorage.setItem(key,JSON.stringify(data))}catch{}$('#zoneStatus').textContent='Histórico NASA POWER · 2025 · datos de rejilla';$('#zoneData').innerHTML=summary.fields.map(f=>`<div class="row"><div>${esc(f.label)}<small>${f.days}/365 días válidos</small></div><strong>${f.value===null?'Sin datos':f.value.toFixed(2)+' '+esc(f.unit)}</strong></div>`).join('');}catch(e){if(id===reviewId)$('#zoneStatus').textContent=`No disponible: ${e.message}. Puedes reintentar o confirmar solo la geometría.`;}finally{if(id===reviewId)btn.disabled=false;}};
 }
 function purpose(){clean();host.innerHTML=header()+`<div class="flow-purpose"><span class="flow-statuspill">✓ Finca confirmada · ${esc(name)} · ${selected.hectares.toFixed(2)} ha</span><h1>Ahora, convierte la información<br>en decisiones para tu finca.</h1><p>NORTEX te ayuda a comprender las condiciones de tu terreno, evaluar sus posibles efectos sobre tus cultivos y comparar opciones de manejo. Tú decides con evidencia y conociendo sus límites.</p><div class="purpose-cards"><div class="card"><small class="eyebrow">01 / SIMULACIÓN Y CONDICIONES</small><h2>Comprende qué siente tu cultivo</h2><p>Explora de forma visual e interactiva qué ocurre en el suelo y en la planta cuando cambia la humedad o la temperatura.</p><button class="primary" data-open="ia">Abrir simulador y predicción →</button></div><div class="card"><small class="eyebrow">02 / SEMILLA DEL SUELO</small><h2>Tu clave con patrón único</h2><p>Genera y germina la Semilla NORTEX de tu parcela para consultar o compartir tu expediente sin usar enlaces complejos.</p><button data-open="suelo">Ver pasaporte y semilla →</button></div><div class="card"><small class="eyebrow">03 / DECISIONES</small><h2>Planifica con criterio</h2><p>Compara alternativas según agua, tiempo y disponibilidad de un lote anual. Los frutales establecidos se conservan.</p><button data-open="plan">Comparar alternativas →</button></div></div><div class="card" style="margin-top:24px"><h2>Lo que conocemos y lo que falta</h2><p>Tu terreno ya tiene una geometría definida. ${climate?'También consultaste el histórico climático de 2025.':'Todavía puedes consultar el clima desde el panel.'} Cultivo, suelo y riego requieren información de campo. Las reglas del prototipo son experimentales; no son diagnósticos ni predicciones validadas.</p><button id="enterDashboard" class="primary">Entrar a mi espacio NORTEX →</button> <button id="changeZone">Cambiar terreno</button></div></div>`;host.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>open(b.dataset.open));$('#enterDashboard').onclick=()=>open('ia');$('#changeZone').onclick=drawMap;}
 function open(page){if(map){map.remove();map=null;}reviewId++;host.hidden=true;document.body.classList.remove('onboarding');onOpen(page);}
 return {start:landing,edit:drawMap};
}
